def prefix_of_tool(path):
    """Installation prefix of an ikos-*-style executable (<prefix>/bin/)."""
    real = os.path.realpath(path)
    return os.path.dirname(os.path.dirname(real))


def site_packages_of_prefix(prefix):
    """Candidate site-packages directories of an ikos install prefix."""
    dirs = [os.path.join(prefix, 'share', 'lotus', 'ikos-api-spec',
                         'analyzer', 'python')]
    for layout in ('libexec/lib', 'lib'):
        dirs += glob.glob(os.path.join(prefix, layout, 'python3.*',
                                       'site-packages'))
    return sorted(dirs, reverse=True)


def bootstrap_ikos(ikos_prefix=None, site_packages=None):
    """Make `import ikos` work against the installed analyzer package."""
    candidates = []
    if site_packages:
        candidates.append(site_packages)
    if ikos_prefix:
        os.environ['IKOS_PREFIX'] = os.path.abspath(ikos_prefix)
        os.environ['LOTUS_IKOS_BIN'] = os.path.join(
            os.path.abspath(ikos_prefix), 'bin')
        candidates += site_packages_of_prefix(ikos_prefix)
    if not ikos_prefix and not site_packages:
        candidates.append(os.path.abspath(os.path.join(
            os.path.dirname(__file__), '..', '..', 'analyzer', 'python')))
    for tool in ('ikos-stub', 'ikos'):
        exe = shutil.which(tool)
        if exe:
            candidates += site_packages_of_prefix(prefix_of_tool(exe))
    for path in candidates:
        if os.path.isfile(os.path.join(path, 'ikos', 'stub.py')):
            sys.path.insert(0, path)
            return path
    sys.stderr.write('error: cannot locate the ikos python package\n')
    if candidates:
        sys.stderr.write('looked in: %s\n' % ', '.join(candidates))
    sys.stderr.write('hints: put ikos-stub on PATH, or pass --ikos-prefix'
                     ' <install-prefix> or --site-packages <dir>\n')
    sys.exit(1)


def load_kit():
    """Import the ikos package and return the modules the tool needs."""
    from ikos import analyzer, api_census, args, colors, log, settings, stub
    return Kit(analyzer, api_census, args, colors, log, settings, stub)


