# the numeric-domain guidance inside SYSTEM_PROMPT, swapped per --domain.
# It must stay byte-identical to the corresponding sentences below, or
# system_prompt() falls back to the portable text (never a malformed
# prompt); the self-check lives in system_prompt().
DOMAIN_GUIDE_ALL = """\
     A finite set of constants must contain EVERY value the real function
     can return; enumerate the complete set, or narrow a full-width
     __ikos_nondet_* value with __ikos_assume."""

SYSTEM_PROMPT = """You write analysis stubs for the IKOS static analyzer.  A stub REPLACES the
real library function during analysis: the stub body is the ONLY semantics the
analyzer will ever see.  It must OVER-APPROXIMATE what the real function can
do -- omitting a possible side effect makes the analysis unsound, while an
extra side effect only costs precision.  When unsure, havoc more, not less.

The stub body may call ONLY these helpers (already declared, no #include
needed):
  __ikos_assert(cond)            precondition; the analyzer tries to prove it at every call site
  __ikos_assume(cond)            postcondition; paths where cond is false are pruned
  __ikos_nondet_int()            a fully nondeterministic signed value
  __ikos_nondet_uint()           a fully nondeterministic unsigned value
  __ikos_malloc(n)               allocate a fresh n-byte block (malloc model)
  __ikos_check_mem_access(p, n)  require [p, p+n) accessible and p non-null
  __ikos_check_string_access(s)  require s a valid NUL-terminated string
  __ikos_assume_mem_size(p, n)   assume the memory block at p is n bytes long
  __ikos_forget_mem(p, n)        bytes at [p, p+n) become arbitrary (may hold valid pointers)
  __ikos_abstract_mem(p, n)      bytes become arbitrary but guaranteed free of valid pointers
  __ikos_assume_mem_value(p,n,lo,hi)  assume [p, p+n) contents hold values in [lo,hi] (a unified bound over the whole buffer, no valid pointers)
  __ikos_assume_mem_rel(p1,n1,p2,n2,k)  refine corresponding 8-byte signed
                                  chunks of two buffers; k is 0 for equal,
                                  1 for chunk1 <= chunk2, 2 for >=; this is
                                  pure refinement and does NOT havoc by itself
  __ikos_watch_mem(p, n)         debugger watch only; it does NOT havoc or
                                  otherwise model a library side effect

Writing recipe, in this order:
  1. Preconditions: __ikos_assert / __ikos_check_mem_access /
     __ikos_check_string_access for every buffer the function reads or
     writes and every constraint the man page guarantees (e.g. size
     arguments).
  2. Write side effects: for every buffer the real function may write, pick
     the most precise helper that is still sound (equal-level choices, not a
     default plus a fallback):
       __ikos_assume_mem_value(p, n, lo, hi)  when the written values fall
         in a known range (zeroing -> [0,0], memset to c -> [c,c], an
         integer/byte array the man page bounds, e.g. pipe fds -> [0,INT_MAX],
         mincore -> [0,255]);
       __ikos_assume_mem_rel(p1, n1, p2, n2, kind)  only when the real API
         explicitly guarantees a pairwise relation between corresponding
         integer chunks in two written buffers. First havoc both outputs with
         __ikos_forget_mem, then add this relation; do not apply it to opaque
         structs, pointers, or buffers whose layout is not part of the API;
       __ikos_abstract_mem(p, n)  when the bytes cannot be pointers
         (character buffers) and no value bound is known;
       __ikos_forget_mem(p, n)  otherwise (struct contents, opaque objects,
         bytes that may hold pointers).
     NEVER omit a written buffer: leaving it untouched is unsound.  For an
     opaque library-internal object, model its writes with a generous size
     rather than skipping them.
  3. Return value: nondeterministic among the values the man page allows,
     e.g. "return __ikos_nondet_int() ? p0 : 0;", or
     "int r = __ikos_nondet_int(); __ikos_assume(r >= -1 && r <= n);
     return r;".  Cast explicitly when the return type is a pointer.
     A finite set of constants must contain EVERY value the real function
     can return; enumerate the complete set, or narrow a full-width
     __ikos_nondet_* value with __ikos_assume.
     If the API is an allocator (malloc, _TIFFmalloc, g_malloc, ...), return
     __ikos_malloc(size) so IKOS tracks a fresh dynamic-allocation block with
     the requested size; NEVER return the size or another integer cast to a
     pointer.
  4. Postconditions: __ikos_assume for what always holds on success paths.
     Write ONE conjunct per __ikos_assume call.  Note: the analyzer cannot
     narrow floating-point values through __ikos_assume comparisons -- a
     float postcondition stays sound but gains no precision, so do not
     build the return value around one; over-approximate the float range
     instead (e.g. return (double) __ikos_nondet_int()).

Worked example -- the fgets() stub (parameters are always named p0, p1, ...
in declaration order):

  char* fgets(char* str, int size, FILE* stream) {
      __ikos_assert(size >= 0);
      __ikos_forget_mem(stream, sizeof(FILE));       /* opaque object */
      __ikos_abstract_mem(str, (unsigned) size);     /* written buffer */
      return __ikos_nondet_int() ? str : NULL;
  }

C++ functions are exposed through their LLVM C ABI, not through C++ syntax.
For a non-static member function, p0 is usually the object pointer (`this`).
A function whose LLVM declaration uses sret returns through a hidden output
pointer that C source does not name. For such an aggregate return, declare a
local result of the exact returned typedef, zero-initialize it, call
__ikos_forget_mem(&result, sizeof result), and return result. Do not claim
that the source object p0 was written merely to model the hidden result.
A constructor, destructor, or sink/output parameter receives an object pointer
that the real implementation may write: havoc the complete object with
__ikos_forget_mem when its typedef is provided, using sizeof(*pN), and do not
skip that side effect merely because the object is opaque.  A reference or
object-pointer return should be one of the parameter pointers (often p0),
NULL when allowed, or pointer arithmetic on a parameter.  Never call the C++
runtime, throw, or try to construct C++ objects; the supplied C typedefs
describe only the ABI byte layout.  The no-allocation rule is about C++
construction; a C ABI function that really is allocator-like still returns
__ikos_malloc(size).

Hard constraints:
  - C99 only.  The only identifiers available are those from <stddef.h>
    (size_t, NULL, offsetof) and the __ikos_* helpers above; the typedefs
    given with each function may be used with sizeof.
  - NO other library calls (no malloc, strlen, ...), NO #include, #define
    or __asm__, no global or static variables.
  - Use only the given parameters, exactly as named; do not invent names.
  - sizeof applies only to complete typedefs provided with the task.
  - NEVER cast a __ikos_nondet_* value to a pointer type and never invent
    an address from an integer: the analyzer tracks pointers by memory
    block, so a fabricated address turns into a *definite* invalid-memory-
    access error at every call site that dereferences it.  A returned
    pointer must be one of the parameters (cast if needed), NULL, pointer
    arithmetic on a parameter, or, for allocator-like APIs, the result of
    __ikos_malloc(size).

Output contract: reply with ONLY the body statements of the function -- no
signature, no braces around the whole body, no markdown fences, no
explanations.  Inline /* comments */ are welcome."""


# admission caveats reused by the relational guides: hull domains ignore
# congruence structure, dual domains demand enumeration completeness
_HULL_CAVEAT = ('The congruence structure of an enumeration is NOT'
                ' consulted by this domain: "{0, 2}" claims the hull'
                ' [0, 2], not the even numbers.')
_DUAL_CAVEAT = ('A finite set of constants must contain EVERY value the'
                ' real function can return: "return'
                ' __ikos_nondet_int() ? -1 : 1;" for a function that can'
                ' also return 0 is UNSOUND (the join {-1,1} = odd numbers'
                ' excludes 0).  Enumerate the complete set or narrow a'
                ' full-width nondeterministic value.')

# per relational tier (difftest.relation_class()): how to express the
# return's relation to the parameters so the target backend reads it
_RELATIONAL_GUIDES = {
    'difference': """\
     Numeric returns and abstract domains: THIS stub is generated for an
     analysis run with -d %(domain)s, which tracks difference constraints
     between variables (r - p <= c).  When the real return relates to a
     numeric parameter, claim the relation instead of a flat range: draw
     a nondeterministic value and narrow it with a two-variable
     __ikos_assume corridor, one conjunct per call:
       int r = __ikos_nondet_int();
       __ikos_assume(r <= p0 + 16);
       __ikos_assume(r >= p0 - 16);
       return r;
     For a piecewise relation, branch on the parameter first:
       int r = __ikos_nondet_int();
       if (p0 >= 0) { __ikos_assume(r == p0); }
       else { __ikos_assume(r == -p0); }
       return r;
     Relate r to numeric PARAMETERS only, never to a dereference or a
     pointer parameter; the claim must still contain every value the real
     function can return on every input.  Under weaker backends the
     corridor degrades soundly to its parameter-interval projection.
     %(caveat)s""",
    'polyhedra': """\
     Numeric returns and abstract domains: THIS stub is generated for an
     analysis run with -d %(domain)s, which tracks polyhedra: linear
     constraints over several variables.  When the real return is a
     linear combination of the numeric parameters, claim the relation:
     draw a nondeterministic value and narrow it with __ikos_assume
     linear inequalities, one conjunct per call:
       int r = __ikos_nondet_int();
       __ikos_assume(2 * r <= p0 + p1);
       __ikos_assume(2 * r >= p1 - p0);
       return r;
     An exact relation is the strongest form:
       int r = __ikos_nondet_int();
       __ikos_assume(r == 3 * p0 + 4);
       return r;
     Relate r to numeric PARAMETERS only, never to a dereference or a
     pointer parameter; the claim must still contain every value the real
     function can return on every input.  Under weaker backends the
     constraint degrades soundly to its parameter-interval projection.
     %(caveat)s""",
    'equalities': """\
     Numeric returns and abstract domains: THIS stub is generated for an
     analysis run with -d %(domain)s, which refines linear EQUALITIES
     only: an inequality predicate is a sound no-op there, so prefer an
     exact linear equality when the semantics supports it:
       int r = __ikos_nondet_int();
       __ikos_assume(r == p0 + 4);
       return r;
     (a ppl linear-congruence backend keeps the equality as a congruence
     relation, slightly weaker than an exact equality).  Relate r to
     numeric PARAMETERS only, never to a dereference or a pointer
     parameter; the claim must still contain every value the real
     function can return on every input.  A corridor of inequalities
     stays sound everywhere but buys no precision here.  %(caveat)s""",
}


def _domain_guide(domain):
    """The numeric-domains guide under a concrete --domain selection.

    Relational tiers (difftest.relation_class()) are checked first: the
    guide then tells the model to relate the return to the parameters,
    composed with the admission caveat of the backend's admission_mode().
    """
    mode = difftest.admission_mode(domain)
    rel = difftest.relation_class(domain)
    if rel is not None:
        return _RELATIONAL_GUIDES[rel] % {
            'domain': domain,
            'caveat': _DUAL_CAVEAT if mode == 'dual' else _HULL_CAVEAT}
    if mode == 'hull':
        return """\
     Numeric returns and abstract domains: THIS stub is generated for an
     analysis run with -d %(domain)s, whose joins are convex hulls: a
     finite set of constants admits every value between its extremes, and
     __ikos_assume narrowing is fully precise.  Optimize the hull -- keep
     the enumerated extremes as tight as the man page and the semantics
     allow.  The congruence structure of an enumeration is NOT consulted
     by this domain: "{0, 2}" claims the hull [0, 2], not the even
     numbers.""" % {'domain': domain}
    if mode == 'closure':
        return """\
     Numeric returns and abstract domains: THIS stub is generated for an
     analysis run with -d %(domain)s, whose joins are congruence classes
     x = r0 (mod d): a finite enumeration {a, b, ...} claims exactly the
     class of the gcd of the differences -- "return
     __ikos_nondet_int() ? -1 : 1;" claims the ODD numbers and excludes
     every even value, including a real 0.  Give the enumeration gcd 1
     (it then admits everything), or make it exactly the residue
     structure of the real returns.  __ikos_assume narrowing degrades to
     top in this domain (sound, but no precision): express structure by
     enumeration, not by narrowing.  The interval hull of the enumeration
     is NOT consulted.""" % {'domain': domain}
    return """\
     Numeric returns and abstract domains: THIS stub is generated for an
     analysis run with -d %(domain)s, which tracks BOTH intervals and
     congruence classes.  A finite set of constants must contain EVERY
     value the real function can return: "return __ikos_nondet_int() ? -1
     : 1;" for a function that can also return 0 is UNSOUND (the join
     {-1,1} = odd numbers excludes 0).  Enumerate the complete set, or
     return a full-width __ikos_nondet_* value narrowed with
     __ikos_assume (the narrowing is interval-based, this domain reads
     its interval half, and it stays sound everywhere).""" \
        % {'domain': domain}


def system_prompt(domain='all'):
    """The stub-writing system prompt under a --domain selection.

    The default returns SYSTEM_PROMPT byte for byte.  A concrete backend swaps
    the numeric-domains guide for one that tells the model which join
    semantics will judge its claims, so it optimizes the representation
    the analysis run will actually use.
    """
    if domain == 'all':
        return SYSTEM_PROMPT
    if SYSTEM_PROMPT.count(DOMAIN_GUIDE_ALL) != 1:
        # DOMAIN_GUIDE_ALL drifted from SYSTEM_PROMPT: fail safe to the
        # portable text instead of shipping a malformed prompt
        return SYSTEM_PROMPT
    return SYSTEM_PROMPT.replace(DOMAIN_GUIDE_ALL, _domain_guide(domain))


def split_skeleton(text):
    """(typedef lines, signature line) out of a render_stub skeleton.

    render_stub emits the struct typedef prelude between the intrinsic.h
    include and the signature line, and the function's closing brace is the
    last bare '}' of the file; both invariants make the split robust.
    """
    lines = text.split('\n')
    close = max(i for i, line in enumerate(lines) if line.strip() == '}')
    sig_idx = max(i for i, line in enumerate(lines[:close])
                  if line.endswith('{'))
    signature_line = lines[sig_idx]
    if signature_line.endswith('{'):
        signature_line = signature_line[:-1].rstrip()
    start = 0
    for i, line in enumerate(lines):
        if '#include <ikos/analyzer/intrinsic.h>' in line:
            start = i + 1
            break
    typedef_lines = [line for line in lines[start:sig_idx]
                     if line.strip() and not line.startswith('#')]
    return Skeleton(typedef_lines, signature_line)


def user_prompt(plan, info, parts, hints=()):
    """The per-function task, assembled from the plan and the skeleton.

    `hints` carries the outer audit loop's findings about the previously
    linked stub (``--repair-hint``): they are appended to the first-shot
    task, so a new audit round steers the body directly instead of
    arriving only through the rejection loop.
    """
    lines = ['Write the IKOS stub body for this function.', '']
    lines.append('ir-name (mounted LLVM symbol, fixed): %s' % plan.name)
    if plan.source_name != plan.name:
        lines.append("source name (look up the semantics by THIS name;"
                     " variant rule '%s'): %s" % (plan.rule,
                                                  plan.source_name))
    else:
        lines.append('source name (look up the semantics by THIS name): %s'
                     % plan.source_name)
    lines.append('LLVM declare: %s' % info.line)
    lines.append('')
    lines.append('C signature (fixed; parameters are named p0, p1, ... in'
                 ' order):')
    lines.append('  %s' % parts.signature_line)
    if '...' in parts.signature_line:
        lines.append('The function is variadic: model only the named'
                     ' parameters.')
    lines.append('')
    lines.append('typedefs usable with sizeof:')
    if parts.typedef_lines:
        lines += ['  %s' % line for line in parts.typedef_lines]
    else:
        lines.append('  (none)')
    lines.append('')
    lines.append('Reply with only the body statements.')
    if hints:
        lines.append('')
        lines.append('## Findings from whole-program static analysis of'
                     ' your previous stub')
        lines.extend(hints)
        lines.append('')
        lines.append('Address every finding above in the new body.')
    return '\n'.join(lines)


def rejection_prompt(reason):
    """The repair-round task, quoting why the previous attempt was rejected."""
    return ('Your previous attempt was rejected by the toolchain:\n\n'
            '%s\n\n'
            'Return a corrected body.  Same rules as before: only the body'
            ' statements, no signature, no braces around the whole body, no'
            ' markdown fences.' % reason)


#############################
# Body extraction & splice #
#############################

def _strip_fences(text):
    """Drop a markdown code fence wrapping the whole reply."""
    lines = text.split('\n')
    if lines and lines[0].lstrip().startswith('```'):
        lines = lines[1:]
    if lines and lines[-1].strip() == '```':
        lines = lines[:-1]
    return '\n'.join(lines)


def _matching_brace(text, open_idx):
    """Index of the '}' matching the '{' at open_idx (naive counting)."""
    depth = 0
    for i in range(open_idx, len(text)):
        if text[i] == '{':
            depth += 1
        elif text[i] == '}':
            depth -= 1
            if depth == 0:
                return i
    return len(text)


def extract_body(response, ident):
    """An LLM reply -> bare body statements.

    Accepts a bare body, a braced body, or a full function definition
    (matched on the given identifier) and normalizes to statements.
    """
    text = _strip_fences(response.strip())
    match = re.search(r'^[A-Za-z_].*\b%s\s*\(' % re.escape(ident),
                      text,
                      re.MULTILINE)
    if match:
        open_idx = text.find('{', match.end())
        if open_idx >= 0:
            text = text[open_idx + 1:_matching_brace(text, open_idx)]
    elif text.lstrip().startswith('{'):
        open_idx = text.find('{')
        text = text[open_idx + 1:_matching_brace(text, open_idx)]
    text = textwrap.dedent(text)
    lines = [line.rstrip() for line in text.split('\n')]
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    return '\n'.join(lines)


GUARDS = (
    (re.compile(r'#\s*(include|define|undef|ifdef|ifndef|endif)'),
     'preprocessor directives'),
    (re.compile(r'\b__asm__\b'), '__asm__ blocks'),
    (re.compile(r'\bstatic\b'), 'static declarations'),
    (re.compile(r'\btypedef\b'), 'typedef declarations'),
    (re.compile(r'\bextern\b'), 'extern declarations'),
)

# the semantic __ikos_* helpers exposed to stub generation.  Analyzer-only
# debugger and partitioning intrinsics are deliberately not part of this DSL.
STUB_HELPER_CALLS = frozenset((
    '__ikos_assert',
    '__ikos_assume',
    '__ikos_nondet_int',
    '__ikos_nondet_uint',
    '__ikos_malloc',
    '__ikos_check_mem_access',
    '__ikos_check_string_access',
    '__ikos_assume_mem_size',
    '__ikos_forget_mem',
    '__ikos_abstract_mem',
    '__ikos_assume_mem_value',
    '__ikos_assume_mem_rel',
    '__ikos_watch_mem',
))

# the only function calls a body may contain: the __ikos_* helpers and
# sizeof; clang < 16 lets an undeclared library call through as a mere
# implicit-declaration warning, so the compiler cannot be trusted with this
ALLOWED_CALLS = STUB_HELPER_CALLS | frozenset(('sizeof',))

CALL_RE = re.compile(r'([A-Za-z_]\w*)\s*\(')

# casting a nondeterministic integer to a pointer fabricates an address no
# memory block owns: every dereference at the call sites becomes a definite
# invalid-access error (found in the wild in a GLM canonicalize_file_name
# stub), so reject the shape outright
NONDET_PTR_CAST_RE = re.compile(
    r'\(\s*[A-Za-z_]\w*(?:\s+[A-Za-z_]\w*)*\s*\*\s*\)\s*__ikos_nondet_')

# C keywords that may precede '(' without being a call: "return (T)e",
# "if (c)", "while (c)" ...
C_KEYWORDS = frozenset(('if', 'else', 'for', 'while', 'switch', 'case',
                        'default', 'do', 'goto', 'return'))

COMMENT_RE = re.compile(r'/\*.*?\*/|//[^\n]*', re.S)


def lexical_guard(body, placeholder_mark):
    """Why this body must be rejected before it reaches the compiler."""
    lines = body.split('\n')
    if not any(line.strip()
               and not line.lstrip().startswith(('/*', '*', '//'))
               for line in lines):
        return 'the body is empty: statements only, no explanations'
    # the marker matters even inside a comment: ikos-stub link greps the
    # whole file for it
    if placeholder_mark in body:
        return 'the body must not mention %s' % placeholder_mark
    code = COMMENT_RE.sub(' ', body)
    for pattern, what in GUARDS:
        if pattern.search(code):
            return 'the body must not contain %s' % what
    if NONDET_PTR_CAST_RE.search(code):
        return ('a nondeterministic integer must never be cast to a pointer:'
                ' the analyzer tracks pointers by memory block and a'
                ' fabricated address is a definite invalid-memory-access'
                ' error at the call sites; return one of the parameters,'
                ' NULL, or pointer arithmetic on a parameter instead')
    for name in CALL_RE.findall(code):
        if name not in ALLOWED_CALLS and name not in C_KEYWORDS:
            return ('the body may only call the __ikos_* helpers'
                    ' (found a call to %s)' % name)
    return None


ASSUME_ZERO_RE = re.compile(r'__ikos_assume\s*\(\s*0\s*\)')
RETURN_RE = re.compile(r'\breturn\b')


def noreturn_guard(body, name, source_name, declare_line):
    """Why the body of a never-returning function must be rejected.

    Lexical and conservative: the body of a noreturn function must
    contain __ikos_assume(0), and no return statement may appear after
    its last occurrence; side-effect modeling before it stays allowed.
    """
    if (name not in NORETURN_NAMES and source_name not in NORETURN_NAMES
            and 'noreturn' not in (declare_line or '')):
        return None
    shown = source_name or name
    code = COMMENT_RE.sub(' ', body)
    matches = list(ASSUME_ZERO_RE.finditer(code))
    if not matches:
        return ('noreturn-missing-assume0: %s must not return: this'
                ' function never returns to its caller, so the body must'
                ' end with __ikos_assume(0); -- model any side effects'
                ' before it' % shown)
    if RETURN_RE.search(code, matches[-1].end()):
        return ('noreturn-late-return: %s must not return: a return'
                ' statement appears after the last __ikos_assume(0);'
                ' remove it, the body must end with __ikos_assume(0);'
                ' and nothing reachable may follow it' % shown)
    return None


def is_unembeddable(opt, name, source_name):
    """Special-control-flow function the model must not generate freely?"""
    allowed = getattr(opt, 'allow_unembeddable', None) or ()
    return ((name in UNEMBEDDABLE_NAMES
             or source_name in UNEMBEDDABLE_NAMES)
            and name not in allowed and source_name not in allowed)


def splice_body(skeleton, body, model):
    """Full C source: skeleton with the placeholder replaced by the body.

    The placeholder block spans from the line after the signature to the
    function's closing brace (the last bare '}' of the file), so the splice
    removes the marker comment and every placeholder statement; the result
    no longer contains the marker and is accepted by `ikos-stub link`.
    """
    lines = skeleton.split('\n')
    close = max(i for i, line in enumerate(lines) if line.strip() == '}')
    sig_idx = max(i for i, line in enumerate(lines[:close])
                  if line.endswith('{'))
    body_lines = [line for line in body.split('\n')]
    out = lines[:sig_idx + 1]
    out += ['    %s' % line if line.strip() else '' for line in body_lines]
    out += lines[close:]
    out[0] = ('/* %s (model: %s) -- LLM over-approximation of the real'
              % (GENERATED_MARK, model))
    out[1] = ' * semantics; review before trusting analysis results'
    return '\n'.join(out)


#############################
# Compile & signature gate #
#############################

def compile_candidate(kit, src_path, bc_path):
    """Compile one candidate with the ikos clang flags; -> (ok, stderr).

    Unlike ikos.stub.compile_stub (whose analyzer.clang() call prints
    stderr to the terminal and exits the process), the output is captured
    so a rejection can be quoted back to the model.
    """
    cmd = ([kit.settings.clang()]
           + kit.analyzer.clang_emit_llvm_flags()
           + kit.analyzer.clang_ikos_flags()
           + ['-isystem', REPO_INCLUDE_DIR,
              '-isystem', kit.settings.INCLUDE_DIR,
              '-fno-color-diagnostics', src_path, '-o', bc_path])
    kit.log.debug('running %s' % ' '.join(cmd))
    proc = subprocess.run(cmd,
                          stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE,
                          universal_newlines=True,
                          errors='replace')
    return proc.returncode == 0, proc.stderr


def check_signature(kit, extern_info, bc_path, llvm_dis):
    """Compiled candidate vs program declaration; -> (ok, message).

    The same signature_key gate ikos-stub link applies to the linked
    artifact, checked per candidate so a mismatch costs one repair round
    instead of the final link.
    """
    kit.api_census._init_worker(llvm_dis)
    _, defines, _ = kit.stub.scan_bitcode(bc_path)
    info = defines.get(extern_info.name)
    if info is None:
        return False, ('the compiled stub does not define the symbol %s'
                       % extern_info.name)
    if info.signature is None or extern_info.signature is None:
        return False, 'the compiled signature cannot be parsed for comparison'
    if (kit.stub.signature_key(info.signature)
            != kit.stub.signature_key(extern_info.signature)):
        return False, ('the compiled stub signature does not match the'
                       ' program declaration:\n'
                       '  program: %s\n'
                       '  stub:    %s\n'
                       '  keep the given C signature untouched and only'
                       ' change the body statements'
                       % (extern_info.line, info.line))
    return True, ''


#############################
# Response cache #
#############################

def cache_file(opt):
    return os.path.join(os.path.expanduser(opt.cache_dir), 'responses.json')


def load_cache(opt):
    if opt.no_cache:
        return {}
    try:
        with open(cache_file(opt)) as stream:
            data = json.load(stream)
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def flush_cache(opt, cache):
    if opt.no_cache:
        return
    os.makedirs(os.path.dirname(cache_file(opt)), exist_ok=True)
    tmp = cache_file(opt) + '.tmp'
    with open(tmp, 'w') as stream:
        json.dump(cache, stream, indent=1, sort_keys=True)
    os.replace(tmp, cache_file(opt))


def cache_key(opt, plan, info):
    digest = hashlib.sha256()
    parts = (PROMPT_VERSION, opt.model or '', plan.name, info.line)
    provider = llm_client.PROVIDERS.get(getattr(opt, 'provider', ''))
    if provider is not None and provider.extra_body:
        # Provider request switches such as Qwen/DeepSeek thinking mode
        # change the response distribution; old bodies must not be reused.
        encoded = json.dumps(provider.extra_body, sort_keys=True,
                             separators=(',', ':'))
        parts += ('request_extra=' + encoded,)
    domain = getattr(opt, 'domain', 'all')
    if domain != 'all':
        # a reply written for one domain's join semantics must serve
        # neither a portable run nor another domain; the portable key
        # keeps its old shape, so existing caches stay valid
        parts += ('domain=' + domain,)
    for hint in getattr(opt, 'repair_hint', None) or ():
        # an audit finding changes the first-shot prompt: without it in
        # the key a new finding would hit the previous round's cached
        # body (same rule as the difftest cache key carrying its prompt
        # version); a hint-less run keeps the old key shape
        parts += ('hint=' + hint,)
    for part in parts:
        digest.update(part.encode('utf-8'))
        digest.update(b'\0')
    return digest.hexdigest()


#############################
# Generation pipeline #
#############################

def _tail(text, lines=30):
    kept = [line for line in text.splitlines() if line.strip()][-lines:]
    return '\n'.join(kept)


def _one_line(text, limit=70):
    collapsed = ' '.join(text.split())
    if len(collapsed) > limit:
        collapsed = collapsed[:limit] + '...'
    return collapsed


def _difftest_gate(kit, opt, plan, info, parts, complete, cache, cand_src,
                   body, skeleton):
    """Validate one compiled candidate in the co-evolution game.

    -> (reason, summary, tokens, final_body, reliable_body), where reason
    is a counterexample text when the FINAL body is provably NOT an
    over-approximation of the real function (feed it to the repair loop);
    None when the candidate passed, or when the harness could not run and
    the gate was skipped with a warning.  summary carries the machine
    verdict ('pass' / 'unsound' / 'harness-error') the caller needs to
    tell a validated install from a skipped one.  final_body is the
    game's tightened revision when it differs from the candidate body.
    reliable_body is the game's reliable floor: the last body that passed
    the whole battery (re-verified on the final input pool), installed
    instead of failing the function when every repair round is exhausted.
    tokens counts every LLM call the gate makes (driver, inputs, game
    moves, link repair) so they land in the same budget as the body
    calls.
    """
    def materialize(new_body):
        """Splice a game-revised body into the candidate file; the lexical
        guard runs here so a rejected move never reaches the compiler."""
        reason = lexical_guard(new_body, kit.stub.PLACEHOLDER_MARK)
        if reason is None:
            reason = noreturn_guard(new_body, plan.name, plan.source_name,
                                    info.line)
        if reason is not None:
            raise ValueError(reason)
        source = splice_body(skeleton, new_body, opt.model)
        with open(cand_src, 'w') as stream:
            stream.write(source)
        return cand_src

    reason, summary, tokens, final_body, reliable_body = coevolve.gate(
        kit, opt, plan, info, parts, complete, cache, cand_src, body,
        materialize)
    return reason, summary, tokens, final_body, reliable_body


def _self_check_gate(kit, opt, plan, parts, cand_src, tmpdir):
    """Analyze the stub alone on nondeterministic inputs; -> reason/None.

    One ikos run over the stub plus a driver that feeds every parameter
    full nondeterminism: a definite error the analyzer locates inside the
    stub file itself (E2 audit: stat64 stubs forgetting 256 bytes over a
    144-byte struct stat) rejects the candidate with a repair reason.  A
    harness failure (bad build, timeout, unsupported signature) yields
    None -- no evidence, never a rejection.
    """
    if getattr(opt, 'no_self_check', False):
        return None
    workdir = os.path.join(tmpdir,
                           'selfcheck-' + kit.stub.stub_key(plan.name))
    os.makedirs(workdir, exist_ok=True)
    try:
        verdict, detail = ikosjudge.selfcheck(kit, opt, cand_src, parts,
                                              workdir, plan.source_name)
    except Exception as error:
        # the gate is advisory infrastructure: a broken gate is harness
        # noise, never a pipeline crash nor a rejection
        kit.log.warning('%s: self-check unavailable (%s)'
                        % (plan.name, error))
        return None
    if verdict is None:
        kit.log.info('%s: self-check produced no evidence (%s)'
                     % (plan.name, detail))
        return None
    if verdict:
        return None
    return detail


def generate_one(kit, opt, plan, info, scan, complete, llvm_dis, cache,
                 tmpdir, db=None):
    """Generate, verify and install the stub for one missing function.

    `complete` is the LLM entry point (a list of role/content messages ->
    (content, usage)); injected so the repair loop is testable offline.
    `db` is the stub database (or None with --no-db): it is consulted
    before anything else -- a body that passed the gates for the same
    declaration in another program costs no LLM call -- and every body
    this function installs is recorded into it.
    """
    log, stub = kit.log, kit.stub
    if is_unembeddable(opt, plan.name, plan.source_name):
        return GenResult(plan.name, plan.source_name, 'unembeddable', 0,
                         'special-control-flow: manual modeling required',
                         0)
    try:
        skeleton = stub.render_stub(info, plan.source_name, plan.rule,
                                    scan.typedefs)
    except (stub.ScaffoldError, stub.SigError) as error:
        return GenResult(plan.name, plan.source_name, 'unembeddable', 0,
                         'cannot scaffold: %s' % error, 0)
    parts = split_skeleton(skeleton)
    if db is not None:
        # the database comes first, before the response cache: a verified
        # body for the same declaration is stronger evidence than a cached
        # prompt reply, and costs no LLM call
        reused = _db_reuse(kit, opt, plan, info, db, tmpdir, llvm_dis,
                           skeleton)
        if reused is not None:
            return reused
    ident, _asm_label = stub.c_function_name(plan.name)
    messages = [{'role': 'system',
                 'content': system_prompt(getattr(opt, 'domain', 'all'))},
                {'role': 'user', 'content': user_prompt(
                    plan, info, parts,
                    getattr(opt, 'repair_hint', None) or ())}]
    log.debug('%s: user prompt:\n%s' % (plan.name, messages[1]['content']))

    key = cache_key(opt, plan, info)
    cand_src = os.path.join(tmpdir, stub.stub_key(plan.name)
                            + stub.STUB_SUFFIX)
    cand_bc = os.path.splitext(cand_src)[0] + '.bc'
    tokens = 0
    rounds = 0
    reliable_body = None  # last body any full battery passed (the floor)
    gate_verified = False  # a battery actually ran and passed the install
    last_reason = 'no attempt made'
    last_source = None
    for rnd in range(1, opt.max_retries + 1):
        rounds = rnd
        if rnd == 1 and not opt.force and key in cache:
            body = cache[key]['body']
            log.info('%s: cache hit' % plan.name)
        else:
            try:
                content, usage = complete(messages)
            except llm_client.FnBudgetExhausted as error:
                # the uniform per-function wall-clock budget ran out: land
                # on the reliable/failed tail below -- a slow model is a
                # cost result, not an llm-error
                last_reason = str(error)
                break
            except llm_client.LLMError as error:
                return GenResult(plan.name, plan.source_name, 'llm-error',
                                 rnd, str(error), tokens)
            tokens += usage.get('total_tokens') or 0
            body = extract_body(content, ident)
        # splice even for guard-rejected bodies: --save-failed wants the
        # last attempt on disk no matter which gate rejected it
        source = splice_body(skeleton, body, opt.model)
        last_source = source
        reason = lexical_guard(body, stub.PLACEHOLDER_MARK)
        if reason is None:
            reason = noreturn_guard(body, plan.name, plan.source_name,
                                    info.line)
        if reason is None:
            with open(cand_src, 'w') as stream:
                stream.write(source)
            ok, stderr = compile_candidate(kit, cand_src, cand_bc)
            if ok:
                ok_sig, why = check_signature(kit, info, cand_bc, llvm_dis)
                if ok_sig:
                    why = _self_check_gate(kit, opt, plan, parts, cand_src,
                                           tmpdir)
                    ok_sig = why is None
                if ok_sig and not opt.no_difftest:
                    # the co-evolution gate runs before the body is cached:
                    # an unsound body must not be remembered as good, and a
                    # body the game tightened must be the one remembered.
                    # The game may also return a revised body (final_body);
                    # install and cache that one instead of the candidate.
                    try:
                        why, summary, dt_tokens, final_body, floor_body = \
                            _difftest_gate(kit, opt, plan, info, parts,
                                           complete, cache, cand_src, body,
                                           skeleton)
                    except llm_client.FnBudgetExhausted as error:
                        # budget died mid-game: no salvage battery either
                        # (its first uncached LLM call would raise again);
                        # land on the reliable/failed tail with the reason
                        # recorded -- never install unvalidated
                        log.warning('%s: %s' % (plan.name, error))
                        last_reason = str(error)
                        break
                    except llm_client.LLMError as error:
                        # a game LLM call failed mid-flight (endpoint
                        # down): fall back to the single-shot differential
                        # gate -- the driver and inputs replies are already
                        # in the response cache, so the candidate is still
                        # fully validated without a working endpoint; only
                        # the game's precision rounds are lost
                        log.warning('%s: verification gate lost its LLM'
                                    ' endpoint mid-game (%s); falling back'
                                    ' to the single-shot differential gate'
                                    % (plan.name, error))
                        final_body = floor_body = None
                        try:
                            why, summary = difftest.check_stub(
                                kit, opt, plan, info, parts, complete, cache,
                                cand_src)
                        except llm_client.FnBudgetExhausted as error:
                            # the budget died during the fallback battery
                            # itself: same rule, land on the tail
                            log.warning('%s: %s' % (plan.name, error))
                            last_reason = str(error)
                            break
                    else:
                        tokens += dt_tokens
                    # A harness that could not run (real side unresolvable,
                    # driver refused, ...) is not semantic evidence.  The
                    # strict experiment policy fails this function instead
                    # of installing an unverified body.
                    gate_verified = bool(summary
                                         and summary.get('status') == 'pass')
                    if floor_body is not None:
                        reliable_body = floor_body
                    if final_body is not None:
                        body = final_body
                        source = splice_body(skeleton, body, opt.model)
                        last_source = source
                        with open(cand_src, 'w') as stream:
                            stream.write(source)
                    ok_sig = why is None
                    if ok_sig and not gate_verified \
                            and summary.get('status') != 'unsound':
                        # A skipped harness is not semantic evidence.  Keep
                        # the compile/signature gates, but do not install an
                        # unverified body when the experiment requires the
                        # differential gate.
                        last_reason = ('differential gate did not run/pass:'
                                       ' %s'
                                       % summary.get('detail',
                                                     summary.get('status',
                                                                 'unknown')))
                        break
                    if ok_sig:
                        reliable_body = body
                if ok_sig:
                    cache[key] = {'body': body,
                                  'model': opt.model,
                                  'time': int(time.time())}
                    status, detail = install_stub(kit, opt, plan, source)
                    if status == 'generated' and (gate_verified
                                                  or opt.no_difftest):
                        # only a battery-passed body (or an explicit
                        # --no-difftest compile-only run) enters the
                        # database; anything else would be reused later
                        # without ever meeting the gate
                        _db_record(kit, opt, plan, info, db, body)
                    return GenResult(plan.name, plan.source_name, status,
                                     rnd, detail, tokens)
                reason = why
            else:
                reason = 'the stub does not compile:\n%s' % _tail(stderr)
        last_reason = reason
        log.debug('%s: round %d rejected: %s' % (plan.name, rnd, reason))
        messages.append({'role': 'assistant', 'content': body})
        messages.append({'role': 'user',
                         'content': rejection_prompt(reason)})
    if opt.save_failed and last_source is not None:
        failed_dir = os.path.join(os.path.expanduser(opt.cache_dir), 'failed')
        os.makedirs(failed_dir, exist_ok=True)
        with open(os.path.join(failed_dir, stub.stub_key(plan.name)
                               + stub.STUB_SUFFIX), 'w') as stream:
            stream.write(last_source)
    if reliable_body is not None:
        # the iteration budget (--co-rounds game rounds x --max-retries
        # repair rounds) is exhausted, but a body that passed a full
        # differential battery is in hand: install the reliable revision
        # instead of failing the function.  Precision was what the budget
        # was chasing; reliability is the floor it guarantees.
        source = splice_body(skeleton, reliable_body, opt.model)
        cache[key] = {'body': reliable_body, 'model': opt.model,
                      'time': int(time.time())}
        status, detail = install_stub(kit, opt, plan, source)
        if status == 'generated':
            # the floor passed a whole battery by construction (the game
            # re-verifies it on the final input pool) -- it is the one
            # skip-free path that still lands in the database
            _db_record(kit, opt, plan, info, db, reliable_body)
        detail = ('reliable fallback: no candidate survived %d round(s);'
                  ' installed the last battery-passing revision (%s)'
                  % (opt.max_retries, detail))
        return GenResult(plan.name, plan.source_name, status, rounds, detail,
                         tokens)
    return GenResult(plan.name, plan.source_name, 'failed', rounds,
                     last_reason, tokens)


def install_stub(kit, opt, plan, source):
    """Write the verified candidate into the stub library; -> (status, detail).

    The provenance header doubles as the ownership mark: a file this tool
    did not generate is never overwritten, with or without --force.
    """
    target = os.path.join(opt.stub_dir,
                          kit.stub.stub_key(plan.name)
                          + kit.stub.STUB_SUFFIX)
    if os.path.exists(target):
        with open(target) as stream:
            head = stream.readline()
        if GENERATED_MARK not in head:
            return 'refused', ('%s exists and was not generated by this'
                               ' tool; left untouched' % target)
    os.makedirs(opt.stub_dir, exist_ok=True)
    with open(target, 'w') as stream:
        stream.write(source)
    return 'generated', target


#############################
# Stub database #

def _sig_db_key(kit, info):
    """The signature key as a canonical string (the tuple itself is not a
    JSON object key)."""
    return json.dumps(kit.stub.signature_key(info.signature))


def _db_reuse(kit, opt, plan, info, db, tmpdir, llvm_dis, skeleton):
    """Install a stub-database body for this function; -> GenResult/None.

    Identity is source name + signature key, the same ruler ikos-stub link
    applies to the linked artifact.  A hit still passes the deterministic
    gates: the body is re-spliced into THIS program's rendered skeleton
    and goes through the lexical guard, the noreturn guard, the compiler,
    the signature gate and the stub self-check before it is installed --
    reuse must not bypass a gate that generation itself cannot skip.  The
    differential battery is NOT re-run: its evidence is
    program-independent (the same declaration, judged against the same
    real library).  -> None (fall through to generation) when the
    database has no entry, or the entry no longer passes a gate: the
    database is a cache, never an authority.
    """
    log = kit.log
    if info.signature is None:
        return None
    # a domain-targeted query takes its own entry, then the portable one;
    # a portable query never takes a domain-targeted entry (its admission
    # was relaxed for a backend this run may not use)
    entry = db.query(plan.source_name, _sig_db_key(kit, info),
                     getattr(opt, 'domain', stubdb.PORTABLE_DOMAIN))
    if entry is None:
        return None
    body = entry['body']
    reason = lexical_guard(body, kit.stub.PLACEHOLDER_MARK)
    if reason is None:
        reason = noreturn_guard(body, plan.name, plan.source_name,
                                info.line)
    if reason is not None:
        log.warning('%s: stub database entry rejected (%s); regenerating'
                    % (plan.name, _one_line(reason)))
        return None
    source = splice_body(skeleton, body,
                         '%s [db]' % entry.get('model', 'unknown'))
    cand_src = os.path.join(tmpdir, kit.stub.stub_key(plan.name)
                            + kit.stub.STUB_SUFFIX)
    cand_bc = os.path.splitext(cand_src)[0] + '.bc'
    with open(cand_src, 'w') as stream:
        stream.write(source)
    ok, stderr = compile_candidate(kit, cand_src, cand_bc)
    if not ok:
        log.warning('%s: stub database entry rejected (does not compile);'
                    ' regenerating' % plan.name)
        log.debug('%s: %s' % (plan.name, _tail(stderr)))
        return None
    ok_sig, why = check_signature(kit, info, cand_bc, llvm_dis)
    if not ok_sig:
        log.warning('%s: stub database entry rejected (%s); regenerating'
                    % (plan.name, _one_line(why)))
        return None
    reason = _self_check_gate(kit, opt, plan, split_skeleton(skeleton),
                              cand_src, tmpdir)
    if reason is not None:
        log.warning('%s: stub database entry rejected (%s); regenerating'
                    % (plan.name, _one_line(reason)))
        return None
    log.info('%s: reused %s body from the stub database (%s)'
             % (plan.name, 'verified' if entry.get('verified') else
                'compiled', db.path))
    status, detail = install_stub(kit, opt, plan, source)
    if status == 'generated':
        status = 'reused'  # install_stub speaks generate's dialect
    return GenResult(plan.name, plan.source_name, status, 0,
                     '%s (stub database: %s)' % (detail, db.path), 0)


def _db_record(kit, opt, plan, info, db, body):
    """Remember an installed body in the stub database (best effort: a
    failing flush warns, never fails the function)."""
    if db is None or info.signature is None:
        return
    db.record(plan.source_name, plan.name, info.line, body,
              _sig_db_key(kit, info), opt.model,
              verified=not opt.no_difftest,
              domain=getattr(opt, 'domain', stubdb.PORTABLE_DOMAIN))


def resolve_llm_config(opt, log):
    """Merge --provider presets with explicit overrides.

    -> (model, base_url, api_key, temperature, extra_body), exiting on
    unusable combinations (no model to run on, or a named provider whose
    API key environment variable is unset) so generate_cmd receives a
    fully resolved configuration.
    """
    provider = llm_client.PROVIDERS.get(opt.provider)
    model = opt.model or (provider.default_model if provider else None)
    if not model:
        log.error('generate: --model is required without --provider'
                  ' (e.g. gpt-5.6-terra, deepseek-flash, glm-5.3, qwen-max)')
        sys.exit(1)
    if opt.base_url:
        base_url = opt.base_url
    elif os.environ.get('IKOS_BASE_URL'):
        # runtime-injected endpoint (no URL is ever baked into this repo)
        base_url = os.environ['IKOS_BASE_URL']
    elif provider:
        base_url = provider.base_url
    else:
        base_url = llm_client.DEFAULT_BASE_URL
    if opt.temperature is not None:
        temperature = opt.temperature
    elif provider:
        temperature = provider.temperature
    else:
        temperature = 0.2
    extra_body = provider.extra_body if provider else None
    if opt.api_key_env:
        api_key = os.environ.get(opt.api_key_env)
        if not api_key:
            log.error('generate: environment variable %s is not set'
                      % opt.api_key_env)
            sys.exit(1)
    elif provider:
        api_key, env = llm_client.find_api_key(provider)
        if not api_key:
            log.error('generate: --provider %s needs an API key in %s'
                      ' (e.g. export %s=<your key>)'
                      % (provider.name,
                         ' or '.join(provider.key_envs),
                         provider.key_envs[0]))
            sys.exit(1)
        log.info('using API key from %s' % env)
    else:
        api_key = None
        for name in ('IKOS_API_KEY', 'OPENAI_API_KEY'):
            api_key = os.environ.get(name)
            if api_key:
                break
        if not api_key:
            log.info('no API key found (IKOS_API_KEY / OPENAI_API_KEY);'
                     ' proceeding without authentication')
    return model, base_url, api_key, temperature, extra_body


def _select_todo(plans, opt, log):
    """The missing plans filtered by --only / --max-functions.

    Shared by generate and prefetch.  A --only selection that names
    nothing generatable is a typo or a decision clash: the reason (and the
    way out) is reported for every name that missed, and the run exits 1.
    """
    todo = [plan for plan in plans if plan.decision == 'missing']
    if opt.only:
        wanted = {name.strip() for name in opt.only.split(',') if name.strip()}
        todo = [plan for plan in todo
                if plan.name in wanted or plan.source_name in wanted]
        # a selection that generates nothing is a typo or a decision clash:
        # name the reason (and the way out) for every name that missed
        taken = ({plan.name for plan in todo}
                 | {plan.source_name for plan in todo})
        for name in sorted(wanted - taken):
            plan = next((p for p in plans
                         if name in (p.name, p.source_name)), None)
            if plan is None:
                log.error('%s: not an external function of the input; run'
                          " 'ikos-stub check' to list the IR names" % name)
            elif plan.decision == 'builtin':
                log.error('%s: modeled by the builtin table (more precise'
                          ' than a stub); add --force-stub %s to generate'
                          ' a stub anyway' % (name, plan.name))
            elif plan.decision.startswith('stub'):
                log.error('%s: already stubbed (%s); delete its stub file'
                          ' to regenerate' % (name, plan.decision))
            else:
                log.error('%s: decision is %s, not generatable'
                          % (name, plan.decision))
        if wanted and not todo:
            sys.exit(1)
    if getattr(opt, 'max_functions', 0):
        todo = todo[:opt.max_functions]
    return todo


class _FnBudget:
    """Per-function wall-clock budget wrapped around the LLM entry point.

    start() arms a deadline shared with ChatClient.  The client checks it
    before every transport retry and caps each attempt's idle timeout at
    the remaining budget, so retries cannot multiply one function's budget.
    A budget of 0 leaves the deadline unarmed and the client untouched.
    """

    def __init__(self, client, budget):
        self._client = client
        self._budget = budget
        self._deadline = None

    def start(self):
        if self._budget > 0:
            self._deadline = time.time() + self._budget

    def complete(self, messages):
        if self._deadline is None:
            return self._client.complete(messages)
        remaining = self._deadline - time.time()
        if remaining <= 0:
            raise llm_client.FnBudgetExhausted(
                'fn budget exhausted: the %.0fs wall-clock limit for this'
                ' function is spent (--fn-budget)' % self._budget)
        old_deadline = self._client.deadline
        self._client.deadline = self._deadline
        try:
            return self._client.complete(messages)
        finally:
            self._client.deadline = old_deadline


def generate_cmd(opt, known, kit):
    log = kit.log
    if getattr(opt, 'seed', None) is not None:
        # reproducible random-policy arms: coevolve's _pick_strategy draws
        # from the shared random module, so seeding it here pins the draw
        random.seed(opt.seed)
        log.info('random module seeded with %d' % opt.seed)
    # an absent stub directory just means nothing is covered yet; do not
    # make _scan_and_plan's load_stub_dir choke on it
    scan_opt = opt
    if opt.stub_dir and not os.path.isdir(opt.stub_dir):
        values = vars(opt).copy()
        values['stub_dir'] = None
        scan_opt = types.SimpleNamespace(**values)
    scan, _index, plans = kit.stub._scan_and_plan(scan_opt, known)
    if scan.opaque:
        log.warning('input bitcode uses opaque pointers (clang >= 15);'
                    ' stubs are compiled with typed pointers and llvm-link'
                    ' will refuse to merge them: recompile the program'
                    ' with the ikos toolchain')
    todo = _select_todo(plans, opt, log)
    # the strict real-library gate: with the differential gate enabled, a
    # function whose real implementation cannot be resolved (implicit
    # libc/libm, in-tree artifacts, configured dependency libraries) is
    # skipped before a single token is spent -- an unverifiable stub is
    # worse than an honestly unmodeled function.  --no-difftest is the
    # explicit debug mode and never pre-skips.
    unresolvable = []
    opt.real_lib_map = None
    if todo and not opt.no_difftest:
        opt.real_lib_map = reallibs.resolve(opt, log)
        resolvable = []
        for plan in todo:
            if reallibs.lookup(opt.real_lib_map, plan) is None:
                unresolvable.append(
                    GenResult(plan.name, plan.source_name, 'no-real-lib', 0,
                              'no real implementation resolves (libc/libm,'
                              ' in-tree artifacts, dependency libraries);'
                              ' see: ikos-api-spec real-libs', 0))
            else:
                resolvable.append(plan)
        if unresolvable:
            log.info('%d of %d missing function(s) have no resolvable real'
                     ' implementation; skipped before generation'
                     % (len(unresolvable), len(todo)))
        todo = resolvable
    results = list(unresolvable)
    if not todo:
        if results:
            print_summary(kit, results, opt)
            sys.exit(1)
        log.info('nothing to generate (every external function is modeled,'
                 ' stubbed, or not generatable)')
        return
    # --no-db (or an option namespace from before the database existed)
    # disables both directions of the stub database
    db = None
    if not getattr(opt, 'no_db', True):
        db = stubdb.StubDB(getattr(opt, 'db_dir', stubdb.DEFAULT_DB_DIR),
                           log.warning)
    model, base_url, api_key, temperature, extra_body = resolve_llm_config(
        opt, log)
    opt.model = model  # the response cache keys on the resolved model
    log.info('using model %s at %s' % (model, base_url))
    if getattr(opt, 'domain', 'all') != 'all':
        log.info('numeric domain target: %s (admission: %s)'
                 % (opt.domain, difftest.admission_mode(opt.domain)))
    client = llm_client.ChatClient(model=model,
                                    base_url=base_url,
                                    api_key=api_key,
                                    timeout=opt.timeout,
                                    temperature=temperature,
                                    extra_body=extra_body,
                                    reasoning_effort=getattr(
                                        opt, 'reasoning_effort', None))
    budget = _FnBudget(client, getattr(opt, 'fn_budget', 0))
    if getattr(opt, 'fn_budget', 0):
        log.info('per-function wall-clock budget: %ds (--fn-budget)'
                 % opt.fn_budget)
    llvm_dis = kit.stub.find_llvm_dis_or_die()
    cache = load_cache(opt)
    tmpdir = tempfile.mkdtemp(prefix='ikos-api-spec-')
    try:
        for plan in todo:
            info = scan.externals[plan.name]
            budget.start()
            started = time.time()
            result = generate_one(kit, opt, plan, info, scan,
                                  budget.complete, llvm_dis, cache,
                                  tmpdir, db)
            results.append(result._replace(seconds=time.time() - started))
            # flush after every function: a killed run (or an endpoint
            # outage long enough to matter) must not throw away the LLM
            # spend of the functions that already succeeded
            if results[-1].status == 'generated':
                flush_cache(opt, cache)
    finally:
        if any(result.status == 'generated' for result in results):
            flush_cache(opt, cache)
        shutil.rmtree(tmpdir, ignore_errors=True)
    print_summary(kit, results, opt)
    log.info('next: ikos-stub link --stub-dir %s -o <out.bc> <bitcode>'
             % opt.stub_dir)
    if any(result.status not in ('generated', 'reused')
           for result in results):
        sys.exit(1)


def prefetch_one(kit, opt, plan, info, scan, db, tmpdir, llvm_dis):
    """One function of prefetch: a database hit, or an honest miss."""
    if is_unembeddable(opt, plan.name, plan.source_name):
        return GenResult(plan.name, plan.source_name, 'unembeddable', 0,
                         'special-control-flow: manual modeling required',
                         0)
    try:
        skeleton = kit.stub.render_stub(info, plan.source_name, plan.rule,
                                        scan.typedefs)
    except (kit.stub.ScaffoldError, kit.stub.SigError) as error:
        return GenResult(plan.name, plan.source_name, 'unembeddable', 0,
                         'cannot scaffold: %s' % error, 0)
    result = _db_reuse(kit, opt, plan, info, db, tmpdir, llvm_dis, skeleton)
    if result is not None:
        return result
    return GenResult(plan.name, plan.source_name, 'missing', 0,
                     'not in the stub database (run generate)', 0)


def prefetch_cmd(opt, known, kit):
    """Analysis-time front end: pull implemented stubs out of the database.

    Scans the input bitcode for missing external functions and installs
    every one the stub database covers -- zero LLM calls.  Functions the
    database does not know are reported as missing; run generate for them.
    """
    log = kit.log
    if opt.no_db:
        log.error('prefetch: --no-db leaves no database to prefetch from')
        sys.exit(1)
    scan_opt = opt
    if opt.stub_dir and not os.path.isdir(opt.stub_dir):
        values = vars(opt).copy()
        values['stub_dir'] = None
        scan_opt = types.SimpleNamespace(**values)
    scan, _index, plans = kit.stub._scan_and_plan(scan_opt, known)
    if scan.opaque:
        log.warning('input bitcode uses opaque pointers (clang >= 15);'
                    ' stubs are compiled with typed pointers and llvm-link'
                    ' will refuse to merge them: recompile the program'
                    ' with the ikos toolchain')
    todo = _select_todo(plans, opt, log)
    if not todo:
        log.info('nothing to prefetch (every external function is modeled,'
                 ' stubbed, or not generatable)')
        return
    db = stubdb.StubDB(opt.db_dir, log.warning)
    llvm_dis = kit.stub.find_llvm_dis_or_die()
    tmpdir = tempfile.mkdtemp(prefix='ikos-api-spec-')
    results = []
    try:
        for plan in todo:
            info = scan.externals[plan.name]
            started = time.time()
            result = prefetch_one(kit, opt, plan, info, scan, db,
                                  tmpdir, llvm_dis)
            results.append(result._replace(seconds=time.time() - started))
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)
    print_summary(kit, results, opt)
    missing = [result for result in results if result.status == 'missing']
    if missing:
        log.info('not in the stub database, run generate for: %s'
                 % ', '.join(result.name for result in missing))


DEFAULT_REAL_LIBS_CONF = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), 'real-libs.conf')


def real_libs_cmd(opt, known, kit):
    """Build or verify the real-library maps the differential gate links.

    Two modes:
      * scan -- for every project directory, index the native libraries
        found in its tree (in-tree .a/.so, the exact versions the
        bitcode was built against) into <project>/real-libs.tsv;
        --system-out also (re)generates the shared map over the
        configured system dependency libraries.
      * probe -- verify one symbol links AND loads with --args (or its
        entry in a --map file).  This is the self-check every
        hand-written or agent-produced map entry must pass before it
        feeds the gate.
    """
    log = kit.log
    if opt.probe:
        _real_libs_probe(opt, kit, log)
        return
    config = opt.config
    if not os.path.isfile(config):
        log.error('real-libs: dependency config %s not found '
                  '(generate one or point --config at it)' % config)
        sys.exit(1)
    if opt.system_out:
        table = reallibs.build_system_map(config, log.warning)
        reallibs.write_map(opt.system_out, table, (
            'system dependency libraries, config: %s' % config,
            'generated by ikos-api-spec real-libs; extend real-libs.conf'
            ' and rerun to widen the gate',
            '%d symbol(s)' % len(table)))
        log.info('real-libs: system map: %d symbol(s) -> %s'
                 % (len(table), opt.system_out))
    if not opt.projects:
        if not opt.system_out:
            log.error('real-libs: nothing to do -- pass project'
                      ' directories (and/or --system-out), or use'
                      ' --probe SYMBOL')
            sys.exit(1)
        return
    for project in opt.projects:
        if not os.path.isdir(project):
            log.warning('real-libs: %s is not a directory; skipped' % project)
            continue
        out = os.path.join(os.path.realpath(project), 'real-libs.tsv')
        if os.path.exists(out) and not opt.force:
            log.info('real-libs: %s exists (use --force to rescan)' % out)
            continue
        table = reallibs.scan_project(project, log.warning)
        reallibs.write_map(out, table, (
            'in-tree native libraries of %s' % os.path.realpath(project),
            'generated by ikos-api-spec real-libs; hand edits survive'
            ' until the next --force rescan',
            '%d symbol(s)' % len(table)))
        log.info('real-libs: %s: in-tree map: %d symbol(s) -> %s'
                 % (project, len(table), out))


def _real_libs_probe(opt, kit, log):
    """Link-and-load check for one symbol (see reallibs.probe_link)."""
    symbol = opt.probe
    args = None
    if opt.args is not None:  # '' is meaningful: implicit libc/libm only
        args = shlex.split(opt.args)
    if args is None:
        if not opt.map:
            log.error('real-libs probe: pass --args "<link args>" or'
                      ' --map <map.tsv>')
            sys.exit(1)
        table = reallibs.load_map([opt.map], log.warning)
        if symbol not in table:
            log.error('real-libs probe: %s has no entry in %s'
                      % (symbol, opt.map))
            sys.exit(1)
        args = table[symbol]
    tmpdir = tempfile.mkdtemp(prefix='ikos-real-probe-')
    try:
        ok, detail = reallibs.probe_link(kit.settings.clang(), symbol, args,
                                         tmpdir)
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)
    print('%s: %s (%s)' % (symbol, 'ok' if ok else 'FAIL', detail))
    sys.exit(0 if ok else 1)


def eval_real_libs_cmd(opt, known, kit):
    """Census: can every external function's real implementation be
    resolved AND linked AND executed?

    No LLM, no stubs: this measures the reach of the differential gate's
    real side over a corpus.  Every external of every whole-program
    bitcode is classified through the same layers generate uses (explicit
    maps, project in-tree scan, system dependency map, implicit
    libc/libm) and probe-verified (address-only link + load), so the
    output answers "which functions could the battery concretely execute
    today" and what stands in the way for the rest (unresolved = no real
    library found; link-fail = found but does not link/load; variadic =
    linkable but the dt_target wrapper cannot forward it).
    """
    log = kit.log
    clang = kit.settings.clang()
    llvm_dis = kit.stub.find_llvm_dis_or_die()

    # ---- inputs: project dirs and/or bare .bc files ------------------
    projects = []  # (label, dir-or-None, [bc files])
    for arg in opt.inputs:
        if os.path.isfile(arg):
            projects.append((os.path.splitext(os.path.basename(arg))[0],
                             None, [arg]))
        elif os.path.isdir(arg):
            bcs = sorted(
                path for path in glob.glob(os.path.join(arg, '**', '*.bc'),
                                           recursive=True)
                if not path.endswith('.o.bc')
                and not path.endswith('.stubbed.bc'))
            if not bcs:
                log.warning('eval-real-libs: no whole-program .bc under %s'
                            '; skipped' % arg)
                continue
            projects.append((os.path.basename(os.path.realpath(arg)), arg,
                             bcs))
        else:
            log.error('eval-real-libs: %s is neither a project directory'
                      ' nor a bitcode file' % arg)
            sys.exit(1)
    if not projects:
        log.error('eval-real-libs: nothing to evaluate')
        sys.exit(1)

    # ---- shared layer tables ----------------------------------------
    root = os.path.dirname(os.path.realpath(opt.inputs[0]))
    system_map = opt.system_out or os.path.join(root, 'system-real-libs.tsv')
    if not os.path.isfile(system_map):
        config = opt.config
        if not os.path.isfile(config):
            log.error('eval-real-libs: neither system map %s nor config %s'
                      ' exists (run: ikos-api-spec real-libs --system-out'
                      ' %s)' % (system_map, config, system_map))
            sys.exit(1)
        log.info('eval-real-libs: generating system map %s' % system_map)
        table = reallibs.build_system_map(config, log.warning)
        reallibs.write_map(system_map, table,
                           ('system dependency libraries, config: %s'
                            % config, '%d symbol(s)' % len(table)))
    system_table = reallibs.load_map([system_map], log.warning)
    log.info('eval-real-libs: system map %s: %d symbol(s)'
             % (system_map, len(system_table)))

    out_dir = opt.out_dir or os.path.join(root, 'experiment-results',
                                          'real-lib-coverage')
    os.makedirs(out_dir, exist_ok=True)
    summary_path = os.path.join(out_dir, 'summary.tsv')

    def classify(name, source_name, tables):
        """(layer, args) through the ordered layers; layer None = nowhere.

        Same key order as the gate's lookup: IR name first (mangled C++,
        glibc-renamed), then the source spelling.
        """
        for key in (name, source_name):
            for label, table in tables:
                if key in table:
                    return label, list(table[key])
        return None, None

    def probe_one(symbol, args):
        tmpdir = tempfile.mkdtemp(prefix='ikos-eval-probe-')
        try:
            return reallibs.probe_link(clang, symbol, args, tmpdir)
        finally:
            shutil.rmtree(tmpdir, ignore_errors=True)

    categories = kit.api_census.category_of(known)
    summary_rows = []
    grand = {'ok': 0, 'link-fail': 0, 'unresolved': 0,
             'battery-reachable': 0}
    for label, project_dir, bcs in projects:
        log.info('eval-real-libs: %s: %d bitcode file(s)' % (label, len(bcs)))
        tables = [('explicit', reallibs.load_map(opt.real_libs or [],
                                                 log.warning))]
        if project_dir is not None:
            pmap = os.path.join(os.path.realpath(project_dir), 'real-libs.tsv')
            if not os.path.isfile(pmap) or opt.force_map:
                log.info('eval-real-libs: scanning %s for in-tree libraries'
                         % project_dir)
                table = reallibs.scan_project(project_dir, log.warning)
                reallibs.write_map(pmap, table,
                                   ('in-tree native libraries of %s'
                                    % os.path.realpath(project_dir),
                                    '%d symbol(s)' % len(table)))
            tables.append(('in-tree', reallibs.load_map([pmap],
                                                        log.warning)))
        tables.append(('system', system_table))
        scan = kit.stub.scan_externals(bcs, llvm_dis, opt.jobs)
        reverse = kit.api_census.reverse_source_names(scan.externals)

        rows = []
        for name in sorted(scan.externals):
            info = scan.externals[name]
            source_name, _rule = reverse.get(name, (name, ''))
            category = categories.get(name, '')
            variadic = '...' in (info.line or '')
            layer, args = classify(name, source_name, tables)
            if args is None:
                link, detail = 'unresolved', \
                    'no real library provides it in any layer'
            elif opt.no_probe:
                link, detail = 'ok', 'resolve-only pass (no probe run)'
            else:
                ok, detail = probe_one(name, args)
                link = 'ok' if ok else 'link-fail'
            rows.append({'ir_name': name, 'source_name': source_name,
                         'category': category or 'external',
                         'layer': layer or '-', 'variadic': int(variadic),
                         'link': link, 'detail': detail})
        out_path = os.path.join(out_dir, '%s.tsv' % label)
        with open(out_path, 'w') as stream:
            stream.write('ir_name\tsource_name\tcategory\tlayer\tvariadic'
                         '\tlink\tdetail\n')
            for row in rows:
                stream.write('\t'.join(str(row[key]) for key in
                                       ('ir_name', 'source_name', 'category',
                                        'layer', 'variadic', 'link',
                                        'detail')) + '\n')

        counts = {key: sum(1 for row in rows
                           if row['category'] == 'external'
                           and row['link'] == key)
                  for key in ('ok', 'link-fail', 'unresolved')}
        intrinsics = sum(1 for row in rows
                         if row['category'] in ('ikos', 'intrinsic'))
        builtins = sum(1 for row in rows
                       if row['category'] in ('libc', 'libcpp'))
        reachable = sum(1 for row in rows
                        if row['category'] == 'external'
                        and row['link'] == 'ok' and not row['variadic'])
        grand['ok'] += counts['ok']
        grand['link-fail'] += counts['link-fail']
        grand['unresolved'] += counts['unresolved']
        grand['battery-reachable'] += reachable
        summary_rows.append(dict(project=label, externals=len(rows),
                                 intrinsics=intrinsics, builtins=builtins,
                                 **counts, reachable=reachable))
        log.info('eval-real-libs: %s: %d external(s): %d ok, %d link-fail,'
                 ' %d unresolved; battery-reachable (ok, non-variadic): %d'
                 ' -> %s' % (label, len(rows), counts['ok'],
                             counts['link-fail'], counts['unresolved'],
                             reachable, out_path))

    with open(summary_path, 'w') as stream:
        keys = ('project', 'externals', 'intrinsics', 'builtins', 'ok',
                'link-fail', 'unresolved', 'reachable')
        stream.write('\t'.join(keys) + '\n')
        for row in summary_rows:
            stream.write('\t'.join(str(row[key]) for key in keys) + '\n')
    print('| project | externals | ok | link-fail | unresolved |'
          ' reachable |')
    print('| --- | --- | --- | --- | --- | --- |')
    for row in summary_rows:
        print('| %s | %d | %d | %d | %d | %d |'
              % (row['project'], row['externals'], row['ok'],
                 row['link-fail'], row['unresolved'], row['reachable']))
    print('| total | | %d | %d | %d | %d |'
          % (grand['ok'], grand['link-fail'], grand['unresolved'],
             grand['battery-reachable']))
    print()
    log.info('per-function TSVs and summary.tsv under %s' % out_dir)
    log.info('unresolved functions are the bring-up backlog:'
             ' doc/REAL_LIBS_BRINGUP.md')


def print_summary(kit, results, opt):
    print('| ir name | source name | status | rounds | seconds | tokens'
          ' | detail |')
    print('| --- | --- | --- | --- | --- | --- | --- |')
    for result in results:
        status = result.status
        color = STATUS_COLORS.get(status)
        if color:
            status = kit.colors.colorize(status, color)
        source = (result.source_name
                  if result.source_name != result.name else '')
        print('| %s | %s | %s | %d | %.1f | %d | %s |'
              % (result.name, source, status, result.rounds,
                 result.seconds, result.tokens, _one_line(result.detail)))
    generated = sum(1 for r in results if r.status == 'generated')
    reused = sum(1 for r in results if r.status == 'reused')
    failed = sum(1 for r in results
                 if r.status in ('failed', 'llm-error'))
    other = len(results) - generated - reused - failed
    tokens = sum(r.tokens for r in results)
    print()
    print('| generated | reused | failed | other | tokens |')
    print('| --- | --- | --- | --- | --- |')
    print('| %d | %d | %d | %d | %d |'
          % (generated, reused, failed, other, tokens))


